function uf_del_mx_after_new() {
	var classid = "";
	if (ds_ddhz.field("ClassId_del").value != "") {	
		classid = ds_ddhz.field("ClassId_del").value ;

		for (var j = ds_ddmx.recordCount - 1 ;j >= 0 ;j--) {
