  var type = typeof obj;
  if(type !== "object" || type === null){    
        if (/string|undefined|function/.test(type)){      
          obj = '"' + obj + '"';    
    }    
        return String(obj); 
  }else{    
    var json = [],arr = (obj && obj.constructor === Array);    
    for(var k in obj){      
      var v = obj[k];      
      var type = typeof v;      
             if (/string|undefined|function/.test(type)) {        
              v = '"' + v + '"';      
        }else 
        if (type === "object") {        
           v = myJsonStringify(v);      
      }      
              json.push((arr ? "" : '"' + k + '":') + String(v));    
       }    
        return (arr ? "[" : "{") + String(json) + (arr ? "]" : "}")  
